local config = {
  ui_story_30930401_1_dialog_content = "Kenapa lama, Navigator? Saking bosannya aku sampai tertidur...",
  ui_story_30930401_2_dialog_content = "Aku sudah bergerak secepat yang kubisa...",
  ui_story_30930401_3_dialog_content = "Jadi, kau mau bicara apa?",
  ui_story_30930401_4_dialog_content = "Eee... Bagaimana cara mengatakannya...",
  ui_story_30930401_5_dialog_content = "Aku banyak mendapat... <color=#FFB400>keluhan</color>... tentangmu akhir-akhir ini.",
  ui_story_30930401_6_dialog_content = "Mereka banyak <color=#FFB400>melaporkanku</color>, aku tahu. Katakan saja apa adanya, jangan berputar-putar dan melapor kepada pejabat Federation.",
  ui_story_30930401_7_dialog_content = "Oh, karena kau sudah tahu, seharusnya ini bukan masalah...",
  ui_story_30930401_8_dialog_content = "Tidak, tunggu, Migard! Kalau kita tidak menganggap serius hal ini, situasi tidak akan berubah!",
  ui_story_30930401_9_dialog_content = "Kalau begitu, aku ingin bicara denganmu empat mata agar kau bisa membantuku memahami... Bagaimana hal semacam itu bisa terjadi.",
  ui_story_30930401_10_dialog_content = "...",
  ui_story_30930401_11_dialog_content = "Menarik. Sepertinya kau juga jenis orang yang sangat tertarik untuk tahu tentang orang lain.",
  ui_story_30930401_12_dialog_content = "Ha? \"Juga\"?",
  ui_story_30930401_13_dialog_content = "Jujur, aku tahu pikiran orang-orang yang mengeluh tentangku itu.",
  ui_story_30930401_14_dialog_content = "\"Migard selalu melihatku dengan pandangan aneh,\" \"Migard selalu mengatakan hal-hal aneh,\"",
  ui_story_30930401_15_dialog_content = "\"Migard berdiri terlalu dekat,\" \"Migard suka diam-diam mengoleksi rambut orang...\"",
  ui_story_30930401_16_dialog_content = "K-kau suka apa?! Aku belum pernah dengar yang terakhir! Hobi macam apa itu?!",
  ui_story_30930401_17_dialog_content = "<color=#FFB400>Gronru</color>, <color=#FFB400>Lilliam</color>, dan <color=#FFB400>Nemesis</color> adalah orang yang melapor kepadamu, 'kan?",
  ui_story_30930401_18_dialog_content = "Wow, benar sekali... Tunggu, aku tidak boleh membocorkan identitas mereka...",
  ui_story_30930401_19_dialog_content = "Tidak apa-apa, aku sudah tahu. Lagi pula, mereka adalah subjek tes favoritku.",
  ui_story_30930401_20_dialog_content = "Dengan kata lain, mereka adalah sasaran utama \"gangguan\"-ku.",
  ui_story_30930401_21_dialog_content = "Dia bahkan mengakui bahwa yang dilakukannya adalah gangguan...",
  ui_story_30930401_22_dialog_content = "Kalian semua menyebutnya \"gangguan\", tapi aku menyebutnya \"penelitian\".",
  ui_story_30930401_23_dialog_content = "Bagaimanapun, sepertinya kau dan yang lain punya perselisihan besar. Sebagai Navigator, aku bertanggung jawab untuk memikirkan solusi...",
  ui_story_30930401_24_dialog_content = "Migard, bisa kau menjelaskan lebih jauh tentang, eh... interaksimu?",
  ui_story_30930401_25_dialog_content = "Aku tidak bisa.",
  ui_story_30930401_26_dialog_content = "Apa?!",
  ui_story_30930401_27_dialog_content = "Cara interogasimu sangat membosankan, aku bosan sekali.",
  ui_story_30930401_28_dialog_content = "Lalu cara seperti apa yang kau inginkan?",
  ui_story_30930401_29_dialog_content = "Bagaimana kalau <color=#FFB400>sandiwara</color>?",
  ui_story_30930401_30_dialog_content = "Apa maksudmu?",
  ui_story_30930401_31_dialog_content = "Kau berpura-pura menjadi Gronru, Lilliam, dan Nemesis, dan aku menjadi diri sendiri.",
  ui_story_30930401_32_dialog_content = "Aku akan memeragakan percakapan kami biasanya, supaya kau bisa lebih memahami <color=#FFB400>interaksi</color> kami kemarin-kemarin.",
  ui_story_30930401_33_dialog_content = "...",
  ui_story_30930401_34_dialog_content = "Heheheheh....",
  ui_story_30930401_35_dialog_content = "*Berkeringat banyak*",
  ui_story_30930401_36_dialog_content = "Kalau kau tidak merasakannya setidaknya sekali, apa pun yang kukatakan mungkin akan kau anggap kabar angin saja.",
  ui_story_30930401_37_dialog_content = "(Aku tidak suka ide ini...)",
  ui_story_30930401_38_dialog_content = "Baiklah... Aku akan berusaha memerankan mereka.",
  ui_story_30930401_39_dialog_content = "Siapa yang pertama?",
  ui_story_30930401_40_option_content = "Gronru",
  ui_story_30930401_41_dialog_content = "...",
  ui_story_30930401_42_dialog_content = "Tik, tik, tik.",
  ui_story_30930401_43_dialog_content = "Apa yang kau lakukan?",
  ui_story_30930401_44_dialog_content = "Hmm? Aku main video game!",
  ui_story_30930401_45_dialog_content = "Tik, tik, tak, dor!",
  ui_story_30930401_46_dialog_content = "Tanpa cela! Rekor baru untuk Illumina Federation! Walau aku sendiri pemegang rekor sebelumnya...",
  ui_story_30930401_47_dialog_content = "Kau agak berlebihan, Navigator.",
  ui_story_30930401_48_dialog_content = "Jangan mengganggu aktingku! Aku berusaha maksimal memerankan Gronru, oke?!",
  ui_story_30930401_49_dialog_content = "Rajin sekali. Kau tahu, orang yang rajin sangat menarik perhatianku...",
  ui_story_30930401_50_dialog_content = "(Sepertinya Migard juga mulai menjiwai perannya...)",
  ui_story_30930401_51_dialog_content = "Gronru, sampai di mana laporan eksperimen yang sebelumnya itu?",
  ui_story_30930401_52_dialog_content = "Ha? A... Eh, tolong beri aku dialog...",
  ui_story_30930401_53_dialog_content = "\"Riset klinis tentang komunikasi interneural di antara berbagai spesies organisme\".",
  ui_story_30930401_54_dialog_content = "Ah! Maksudmu laporan tentang \"komplikasi inter-bla bla di antara berbagai sesuatu\"!",
  ui_story_30930401_55_dialog_content = "Ini dia!",
  ui_story_30930401_56_dialog_content = "Oke.",
  ui_story_30930401_57_dialog_content = "A-apa yang kau lakukan, Migard?",
  ui_story_30930401_58_dialog_content = "Bau yang enak sekali.",
  ui_story_30930401_59_dialog_content = "Kau baru ganti sabun mandi, Gronru?",
  ui_story_30930401_60_dialog_content = "(Apa dia menggoda?)",
  ui_story_30930401_61_dialog_content = "Aku juga sebelumnya menggunakan bau ini.",
  ui_story_30930401_62_dialog_content = "Sepertinya kita makin dekat...",
  ui_story_30930401_63_dialog_content = "Oh, kamar mandiku cukup besar. Mau lihat?",
  ui_story_30930401_64_dialog_content = "Sial, ini bukan pertanda baik! Tak heran dia melaporkannya!!",
  ui_story_30930401_65_dialog_content = "Kau bisa dipenjara karena tindakan semacam ini!!",
  ui_story_30930401_66_dialog_content = "Kenapa? Aku hanya menunjukkan rasa senang karena kita menyukai hal yang sama.",
  ui_story_30930401_67_dialog_content = "Tidak, Migard, yang kau lakukan adalah bersiap melakukan tindakan kriminal.",
  ui_story_30930401_68_dialog_content = "Ah, membosankan sekali. Kupikir kau lebih seru dari ini, Navigator.",
  ui_story_30930401_69_dialog_content = "Sama sekali tidak ada yang \"seru\" tentang ini... Kau harus mengendalikan hasratmu, Migard...",
  ui_story_30930401_70_dialog_content = "Tapi hasratku adalah yang menjadikanku dan Black Umbrella Laboratories seperti sekarang ini.",
  ui_story_30930401_71_dialog_content = "Ilmuwan tanpa hasrat bukanlah ilmuwan, Navigator. Sesederhana itu.",
  ui_story_30930401_72_dialog_content = "Itu hal yang berbeda!",
  ui_story_30930401_73_dialog_content = "Heheh, kau imut sekali ketika resah seperti ini...",
  ui_story_30930401_74_dialog_content = "Kemudian, peranmu berikutnya adalah...",
  ui_story_30930401_75_option_content = "Lilliam",
  ui_story_30930401_76_dialog_content = "Settt, setttt.",
  ui_story_30930401_77_dialog_content = "Settt, setttt, seeeettttt.",
  ui_story_30930401_78_dialog_content = "Dan suara aneh apa itu?",
  ui_story_30930401_79_dialog_content = "Suara Lilliam menyapu lantai...",
  ui_story_30930401_80_dialog_content = "Karena ini Lilliam, bukankah dia seharusnya melakukan tugas sebagai pelayan dengan tenang?",
  ui_story_30930401_81_dialog_content = "Tergantung Lilliam yang mana, tapi... Heheh, aku suka mereka semua.",
  ui_story_30930401_82_dialog_content = "Peringatan. Menerjemahkan: Terdeteksi niat mesum. Hati-hati.",
  ui_story_30930401_83_dialog_content = "Oh, kita sudah mulai? Kalau begitu, aku juga harus serius...",
  ui_story_30930401_84_dialog_content = "Oh, Lilliam? Mau coba minuman probiotik baru dari Black Umbrella Laboratories ini?",
  ui_story_30930401_85_dialog_content = "Pertanyaan. Menerjemahkan: Tolong definisikan \"minuman probiotik\".",
  ui_story_30930401_86_dialog_content = "Cuma jus buah! Sangat segar, dan konon buah jenis ini...",
  ui_story_30930401_87_dialog_content = "Adalah penambah gairah.",
  ui_story_30930401_88_dialog_content = "Pertanyaan, eh, maksudku, akses ditolak! Tolong jangan membuat pernyataan yang membuat tidak nyaman seperti itu!!",
  ui_story_30930401_89_dialog_content = "Tapi kenapa? Aku cuma ingin memahamimu lebih baik, Lilliam... Kalian semua.",
  ui_story_30930401_90_dialog_content = "Semua bilang Lilliam No. 1 hanyalah robot pelayan tanpa jiwa... Tapi kurasa tidak begitu.",
  ui_story_30930401_91_dialog_content = "Sebaliknya, menurutku setiap benda hidup mampu merasakan berbagai emosi, baik atau buruk.",
  ui_story_30930401_92_dialog_content = "Bahkan Diving Spines milikku terasa seperti marah kalau aku tidak mensterilkannya dengan benar.",
  ui_story_30930401_93_dialog_content = "Ekspresi terkejut: Bisakah benda itu berperilaku seperti hewan peliharaan yang manja?",
  ui_story_30930401_94_dialog_content = "Aku cuma bercanda. Tapi, yang sungguh aku inginkan adalah... memicu emosi darimu, Lilliam.",
  ui_story_30930401_95_dialog_content = "Kau bukan robot, tapi orang sepertiku, Lilliam. Dan seperti aku, kau pasti punya hasrat dan perasaan juga...",
  ui_story_30930401_96_dialog_content = "Bahaya terdeteksi! Sadarlah, Migard! Aku bukan Lilliam sungguhan!!!",
  ui_story_30930401_97_dialog_content = "A-ah, maaf. Aku terhanyut dalam peran... Semua salahmu, Navigator. Kau tahu, kau itu jago dalam berakting.",
  ui_story_30930401_98_dialog_content = "Kemudian, peranmu berikutnya adalah...",
  ui_story_30930401_99_option_content = "Nemesis",
  ui_story_30930401_100_dialog_content = "Hei!",
  ui_story_30930401_101_dialog_content = "Ha!!",
  ui_story_30930401_102_dialog_content = "Halo, Nemesis! Sedang kalistenik, ya?",
  ui_story_30930401_103_dialog_content = "Ini... latihan! Latihan untuk menjaga dan menegakkan keadilan!",
  ui_story_30930401_104_dialog_content = "Apa ada gerakanku yang salah? Bentuknya salah?",
  ui_story_30930401_105_dialog_content = "Tidak, gerakanmu sangat baik. Cuma... Sepertinya kaki dan tanganmu punya pikiran sendiri.",
  ui_story_30930401_106_dialog_content = "Ehem! I-itu tidak penting! Omong-omong... Sepanjang kau punya hati yang adil, kita akan selalu menjadi kawan seperjuangan!",
  ui_story_30930401_107_dialog_content = "Apa itu artinya kau akan menghukum orang kalau dia melawan keadilan, Nemesis?",
  ui_story_30930401_108_dialog_content = "<size=50>Tanpa ragu!</size>",
  ui_story_30930401_109_dialog_content = "(Argh... Bagaimana bisa Nemesis bicara seperti ini sepanjang waktu? Tenggorokanku mau menyerah rasanya...)",
  ui_story_30930401_110_dialog_content = "Aku mengerti... Pelaku kejahatan harus dihukum, ya...",
  ui_story_30930401_111_dialog_content = "...",
  ui_story_30930401_112_dialog_content = "Migard... Sejak kapan kau bersikap sangat mencurigakan?",
  ui_story_30930401_113_dialog_content = "Mencurigakan? Aku? Tapi aku tidak mengatakan apa-apa.",
  ui_story_30930401_114_dialog_content = "Hanya saja... Saat gadis sepertimu berlatih seperti ini, tubuhmu memancarkan... daya tarik yang tak tertahankan.",
  ui_story_30930401_115_dialog_content = "Apa sebenarnya yang kau mau, Migard dari Black Umbrella Laboratories? Keadilan tidak bertele-tele.",
  ui_story_30930401_116_dialog_content = "Aku, eh... Aku mau...",
  ui_story_30930401_117_dialog_content = "Menyerahkan diri.",
  ui_story_30930401_118_dialog_content = "Walau aku sudah sepenuhnya siap, kata-katamu masih mengejutkanku.",
  ui_story_30930401_119_dialog_content = "Bicaralah. Hukum Illumina Federation mana yang telah kau langgar?",
  ui_story_30930401_120_dialog_content = "T-tidak, aku belum melanggar hukum apa pun, tapi aku akan melakukannya...",
  ui_story_30930401_121_dialog_content = "Terhadap seorang... pembela keadilan...",
  ui_story_30930401_122_dialog_content = "A-apa?! Apa yang kau rencanakan?!",
  ui_story_30930401_123_dialog_content = "Sebagai General Inspector, bagaimana kau bisa menjaga tingkat kewaspadaan setinggi itu sepanjang hari, Nemesis?",
  ui_story_30930401_124_dialog_content = "Bagaimana bisa kau menahan godaan paling kuat sekali pun, hanya untuk mematuhi aturan-aturan usang dan kaku itu? Aku benar-benar ingin tahu...",
  ui_story_30930401_125_dialog_content = "Maukah kau kuajak ke laboratoriumku sebentar?",
  ui_story_30930401_126_dialog_content = "Jangan lupa, Migard, aku bukan Nemesis sungguhan...",
  ui_story_30930401_127_dialog_content = "Ah, aku hampir lupa.",
  ui_story_30930401_128_dialog_content = "Kau memang punya bakat akting, Navigator. Sekarang kau pun mulai menarik perhatianku...",
  ui_story_30930401_129_dialog_content = "Kemudian, peranmu berikutnya adalah...",
  ui_story_30930401_130_option_content = "Kupikir kita sudah selesai",
  ui_story_30930401_131_dialog_content = "Cukup, cukup! Kita harus berhenti...",
  ui_story_30930401_132_dialog_content = "Kalau kita terus melanjutkan, aku takut kau tidak akan bisa mengendalikan diri, Migard...",
  ui_story_30930401_133_dialog_content = "...",
  ui_story_30930401_134_dialog_content = "...",
  ui_story_30930401_135_dialog_content = "Heheh.",
  ui_story_30930401_136_dialog_content = "Terlambat! Migard sudah melihatku sebagai <color=#FFB400>subjek tes</color>!!",
  ui_story_30930401_137_dialog_content = "Oh, tentu saja. Kupikir aku tidak akan sebosan sebelumnya mulai sekarang...",
  ui_story_30930401_138_dialog_content = "T-tunggu, Migard! Aku tahu masalahnya sekarang!",
  ui_story_30930401_139_dialog_content = "Hmm? Masalah apa?",
  ui_story_30930401_140_dialog_content = "Masalah yang orang-orang laporkan tentangmu! Masalahnya...",
  ui_story_30930401_141_option_content = "Adalah caramu \"meneliti\" setiap orang!",
  ui_story_30930401_142_dialog_content = "Tidak semua orang seperti kau, Migard! Tidak semua punya keinginan meneliti yang kuat sampai hampir menyimpang seperti itu...",
  ui_story_30930401_143_dialog_content = "Kau tidak menyembunyikan emosi, dan itu bagus! Kejujuran itu baik!",
  ui_story_30930401_144_dialog_content = "Tapi di sisi lain, mengganggu orang itu bagaimanapun tetaplah perilaku yang salah.",
  ui_story_30930401_145_dialog_content = "...",
  ui_story_30930401_146_dialog_content = "Lain kali, bagaimana kalau kau mengubah pendekatanmu? Jangan terlalu agresif, dan jangan melakukan tindakan seperti ini tanpa izin orang terkait.",
  ui_story_30930401_147_dialog_content = "Atau mungkin lakukan penelitianmu lewat tulisan! Dengan begitu, bahkan orang yang tidak bersedia kau teliti secara langsung bisa...",
  ui_story_30930401_148_option_content = "Menjadi subjek tes pilihanmu!",
  ui_story_30930401_149_dialog_content = "Tidak semua orang nyaman dengan apa yang kau sebut \"penelitian\", Migard!",
  ui_story_30930401_150_dialog_content = "Jadi, bagaimana kalau, eh... kau mulai dengan orang yang sudah dekat denganmu? Teliti mereka terlebih dulu...",
  ui_story_30930401_151_dialog_content = "Kemudian, perlahan kembangkan basis subjekmu seiring waktu. Itu metode ilmiah yang cukup masuk akal, 'kan?",
  ui_story_30930401_152_dialog_content = "...",
  ui_story_30930401_153_dialog_content = "Kau dengar, Migard?!",
  ui_story_30930401_154_dialog_content = "Aku sungguh ingin membantu! Tidak hanya kau, tapi juga yang lain...",
  ui_story_30930401_155_dialog_content = "Heheh... Heheheheh....",
  ui_story_30930401_156_dialog_content = "Bisa kau tidak tertawa seperti itu?! Insting bertahan hidupku sudah memintaku untuk segera pergi dari sini...",
  ui_story_30930401_157_dialog_content = "Menarik.",
  ui_story_30930401_158_dialog_content = "Kau benar-benar menarik, Navigator.",
  ui_story_30930401_159_dialog_content = "Aku telah mengambil keputusan.",
  ui_story_30930401_160_dialog_content = "Keputusan apa...",
  ui_story_30930401_161_dialog_content = "Kau akan menjadi subjek tesku yang terbaru...",
  ui_story_30930401_162_dialog_content = "Apa? Tidak! Tunggu, maksudku...",
  ui_story_30930401_163_dialog_content = "Kau akan menunjukkan PERSISNYA cara meneliti orang lain, langkah demi langkah...",
  ui_story_30930401_164_dialog_content = "Tunggu, Migard!",
  ui_story_30930401_165_dialog_content = "Tidak ada jalan kembali, Navigator...",
  ui_story_30930401_166_dialog_content = "Migard, tidak!!!",
  ui_story_30930601_1_dialog_content = "(Aku banyak bermain game dengan Gronru belakangan ini.)",
  ui_story_30930601_2_dialog_content = "(Akibatnya, aku jadi ikut-ikutan kebiasaan buruknya dan juga mulai membantu pekerjaannya.)",
  ui_story_30930601_3_dialog_content = "Kamu tahu game yang lebih menyeramkan dari ini?",
  ui_story_30930601_4_dialog_content = "Seharusnya ada label 18+ pada sampul game semacam ini...",
  ui_story_30930601_5_dialog_content = "Dialognya penuh dengan umpatan dan kata-kata cabul.",
  ui_story_30930601_6_dialog_content = "Sebaiknya ada label besar bertuliskan \"Parental Advisory: Explicit Content\" pada game ini.",
  ui_story_30930601_7_dialog_content = "Bahkan para gamer terhebat di Illumina pun tak bakal mau main game seperti ini...",
  ui_story_30930601_8_dialog_content = "Biasanya, kami hanya kemari untuk mengantar beberapa material, tidak lebih.",
  ui_story_30930601_9_dialog_content = "Tapi, saat menyadari bahwa kiriman ini ditujukan untuk <color=#FFB400>Migard</color>, dan alamatnya adalah <color=#FFB400>lounge miliknya</color>...",
  ui_story_30930601_10_dialog_content = "Kuakui kali ini kamu benar, Gronru.",
  ui_story_30930601_11_dialog_content = "Kamu juga berpendapat begitu?",
  ui_story_30930601_12_dialog_content = "Ya... Lagi pula, aku sudah menerima siksaan darinya.",
  ui_story_30930601_13_dialog_content = "Kuberi tahu, ya... Senyumnya bukan sesuatu yang mudah dilupakan.",
  ui_story_30930601_14_dialog_content = "Itu sebabnya aku punya strategi!",
  ui_story_30930601_15_dialog_content = "Aku paham! Kamu ingin bersekutu denganku, 'kan?",
  ui_story_30930601_16_dialog_content = "Ya, mungkin akan berhasil... Dengan menyatukan kekuatan, mungkin kita bisa mengalahkan bos yang kuat seperti dia!",
  ui_story_30930601_17_dialog_content = "Kamu benar! Tapi, itu baru langkah pertama dari rencanaku.",
  ui_story_30930601_18_dialog_content = "Langkah selanjutnya...",
  ui_story_30930601_19_dialog_content = "Aku keluar dulu!",
  ui_story_30930601_20_dialog_content = "<size=50>Sekarang terserah padamu, PlayerName!!</size>",
  ui_story_30930601_21_dialog_content = "<size=45>Sekarang terserah padamu!</size>",
  ui_story_30930601_22_dialog_content = "<size=40>Terserah padamu!</size>",
  ui_story_30930601_23_dialog_content = "<size=35>Padamu!</size>",
  ui_story_30930601_24_dialog_content = "Eh?! Ini sungguh-sungguh bagian dari rencanamu?!",
  ui_story_30930601_25_dialog_content = "Kamu ingin aku mengalahkan bos yang memiliki HP tinggi seperti Migard seorang diri?!",
  ui_story_30930601_26_dialog_content = "……",
  ui_story_30930601_27_dialog_content = "(Setelah sering bermain game bersama, kupikir aku dan Gronru berteman dekat...)",
  ui_story_30930601_28_dialog_content = "(Lain kali aku harus memilih rekan tim yang lebih baik.)",
  ui_story_30930601_29_dialog_content = "Selama aku menaruhnya di depan pintu Migard...",
  ui_story_30930601_30_dialog_content = "Pekerjaanku selesai, dan aku bisa pergi dari sini.",
  ui_story_30930601_31_dialog_content = "Aku hanya harus melakukannya dengan baik dan tenang...",
  ui_story_30930601_32_dialog_content = "Atau kamu bisa saja langsung memberikannya padaku.",
  ui_story_30930601_33_dialog_content = "Yah, kalau kamu bersikeras...",
  ui_story_30930601_34_dialog_content = "Hah?",
  ui_story_30930601_35_dialog_content = "(Tahu-tahu pertempuran bos pun dimulai.)",
  ui_story_30930601_36_dialog_content = "(Tapi, kali ini penampilan sang bos berbeda dengan sebelumnya. Dia hanya mengenakan pakaian biasa.)",
  ui_story_30930601_37_dialog_content = "(Beberapa elemen pada pakaiannya memperjelas bentuk tubuhnya... Kurasa itu penampilan yang dianggap trendi...)",
  ui_story_30930601_38_dialog_content = "(Walaupun begitu, aku tak boleh meremehkannya. Dia sudah menggunakan skill pertamanya... Aku sangat ketakutan.)",
  ui_story_30930601_39_dialog_content = "(Aku tak bisa bergerak sama sekali sekarang.)",
  ui_story_30930601_40_dialog_content = "Tubuhmu lumpuh, PlayerName? Heheh... Apa boleh buat. Lagi pula kamu masih muda.",
  ui_story_30930601_41_dialog_content = "Eh... T-tidak, kok. Aku hanya kemari untuk mengantarkan material eksperimen. Itu saja. Aku mau pergi dulu...",
  ui_story_30930601_42_dialog_content = "Jangan tergesa-gesa begitu.",
  ui_story_30930601_43_dialog_content = "(Itu skill keduanya... Penindasan.)",
  ui_story_30930601_44_dialog_content = "(Dia mengangkat tubuhku dengan mencengkeram kerah bajuku! Kakiku sampai terangkat dari tanah!)",
  ui_story_30930601_45_dialog_content = "*Tergagap* Lepaskan... lepaskan aku...",
  ui_story_30930601_46_dialog_content = "Sepertinya tubuhmu masih kurang tinggi.",
  ui_story_30930601_47_dialog_content = "Yah, karena sudah kemari... Jangan kira kamu bisa pergi begitu saja.",
  ui_story_30930601_48_dialog_content = "Mau masuk dan menemaniku sebentar?",
  ui_story_30930601_49_dialog_content = "(Itu skill ketiganya... Mengubah medan tempur.)",
  ui_story_30930601_50_dialog_content = "(Aduh, tanpa sadar aku sudah memejamkan mataku... Tapi, aku terlalu takut untuk membukanya.)",
  ui_story_30930601_51_dialog_content = "Tak ada yang perlu ditakutkan.",
  ui_story_30930601_52_dialog_content = "Lihat, 'kan?",
  ui_story_30930601_53_dialog_content = "……",
  ui_story_30930601_54_dialog_content = "Ini... laboratorium?",
  ui_story_30930601_55_dialog_content = "Tapi, tadinya kupikir kita berada di pintu masuk lounge-mu.",
  ui_story_30930601_56_dialog_content = "Jangan-jangan pintu itu... sebenarnya portal?",
  ui_story_30930601_57_dialog_content = "Yang bisa membuat kita melintasi waktu dan ruang?",
  ui_story_30930601_58_dialog_content = "Ada apa? Kamu tidak suka kamarku, ya?",
  ui_story_30930601_59_dialog_content = "I-ini unik sekali! Tenang dan misterius!",
  ui_story_30930601_60_dialog_content = "Tentu saja pasti ada latar belakang yang detail seperti ini di ruang bos...",
  ui_story_30930601_61_dialog_content = "Sepertinya kamu sering bermain dengan Gronru akhir-akhir ini.",
  ui_story_30930601_62_dialog_content = "Bahkan beberapa pola bicaramu sampai mirip dengan dia.",
  ui_story_30930601_63_dialog_content = "Hehehe... Kecocokan seperti ini... Sulit ditolak.",
  ui_story_30930601_64_dialog_content = "K-kamu... Aku... Eh...",
  ui_story_30930601_65_dialog_content = "Bahkan kamu juga seperti dia saat merasa malu...",
  ui_story_30930601_66_dialog_content = "Ketegangan dan kegembiraan semacam ini dapat menimbulkan respons saraf yang kuat.",
  ui_story_30930601_67_dialog_content = "Detak jantung jadi lebih cepat dan pembuluh darah melebar, lalu akhirnya wajah kita jadi merona.",
  ui_story_30930601_68_dialog_content = "Dalam kasus tertentu, keringat kita bisa tak terkendali.",
  ui_story_30930601_69_dialog_content = "*Sroot*",
  ui_story_30930601_70_dialog_content = "... Tingkahmu aneh, tahu?",
  ui_story_30930601_71_dialog_content = "Omong-omong, ini... spesimen biologis?",
  ui_story_30930601_72_dialog_content = "Buku dan material berserakan di lantai. Kamu juga memakai jas lab.",
  ui_story_30930601_73_dialog_content = "Kamu sedang bekerja, ya? Kalau tidak salah ingat, seharusnya hari ini kamu cuti.",
  ui_story_30930601_74_dialog_content = "Istirahat dari pekerjaan itu boleh saja, tapi karier butuh waktu dan perhatian penuh.",
  ui_story_30930601_75_dialog_content = "Bahkan meskipun bekerja lembur dan tidak dibayar...",
  ui_story_30930601_76_dialog_content = "Dalam beberapa kasus, lingkungan yang nyaman bisa meningkatkan produktivitas.",
  ui_story_30930601_77_dialog_content = "Kalau begitu, aku tak ingin mengganggu pekerjaanmu...",
  ui_story_30930601_78_dialog_content = "Sebenarnya, aku senang dengan gangguanmu. Aku mengalami kendala dalam penelitianku.",
  ui_story_30930601_79_dialog_content = "Semua eksperimenku yang sebelumnya gagal total, tapi untungnya Gronru bisa mencarikanku <color=#FFB400>botol berisi pelarut ini</color>.",
  ui_story_30930601_80_dialog_content = "Oh... Memangnya apa gunanya?",
  ui_story_30930601_81_dialog_content = "Ini digunakan dalam pemisahan dan pemurnian.",
  ui_story_30930601_82_dialog_content = "Intinya, aku mencoba memisahkan sesuatu dari kristal dengan pemanasan dan penggunaan pelarut ini.",
  ui_story_30930601_83_dialog_content = "Melalui perbedaan kelarutan berbagai senyawa padat dalam larutan...",
  ui_story_30930601_84_dialog_content = "Eh... Kamu terlihat agak kebingungan.",
  ui_story_30930601_85_dialog_content = "Begini, misalnya, kamu dan Barton pergi ke sauna bersama.",
  ui_story_30930601_86_dialog_content = "Karena kulitnya tebal, dia bisa menahan suhu panas sauna selama 30 menit tanpa berkeringat.",
  ui_story_30930601_87_dialog_content = "Sedangkan kamu, tubuhmu akan berubah jadi genangan air kalau lewat 3 menit saja di sana.",
  ui_story_30930601_88_dialog_content = "Nah, aku bisa mengeluarkan Barton dari sauna tanpa kamu.",
  ui_story_30930601_89_dialog_content = "Maksudmu, kamu mau meninggalkanku terbakar di sauna?!",
  ui_story_30930601_90_dialog_content = "Tapi, metode ini punya keterbatasan, terutama saat memulai dari nol.",
  ui_story_30930601_91_dialog_content = "Memilih pelarut yang tepat, yang tak bisa bereaksi dengan objek murni yang kucoba ambil, sangat penting. Di sinilah letak kesulitannya.",
  ui_story_30930601_92_dialog_content = "Misalnya, karena ketidakcocokan, gaya hidup lama dan indah akan menjadi \"pelarut\" yang tidak bereaksi dengan Barton.",
  ui_story_30930601_93_dialog_content = "Aku menghilangkan cukup banyak pelarut potensial dalam penyaringan awal.",
  ui_story_30930601_94_dialog_content = "Apa aku perlu memberi perbandingan lain untuk proses penyaringan?",
  ui_story_30930601_95_dialog_content = "Itu seperti...",
  ui_story_30930601_96_dialog_content = "<color=#e8d9bb>Lalu, Migard menghabiskan waktu sekitar satu jam untuk memberi PlayerName penjelasan singkat akan pekerjaannya.</color>",
  ui_story_30930601_97_dialog_content = "(Kepalaku jadi penuh perbandingan aneh Migard... Rasanya ini tidak ada kaitannya dengan sains.)",
  ui_story_30930601_98_dialog_content = "(Tapi, wajah Migard terlihat ceria... Penelitian ini benar-benar membuatnya bergairah.)",
  ui_story_30930601_99_dialog_content = "Omong-omong, setelah mempertimbangkan segalanya, ini saatnya eksperimen, 'kan?",
  ui_story_30930601_100_dialog_content = "Benar.",
  ui_story_30930601_101_dialog_content = "Kalau begitu, aku tak akan mengganggumu lagi...",
  ui_story_30930601_102_dialog_content = "Lagi pula, aku malah akan mengusikmu kalau terus berada di sini.",
  ui_story_30930601_103_dialog_content = "Aku pergi dulu, ya. Aku yakin eksperimenmu akan berhasil, Migard!",
  ui_story_30930601_104_dialog_content = "Benar juga.",
  ui_story_30930601_105_dialog_content = "Aku akan mengabarimu, PlayerName.",
  ui_story_30930601_106_dialog_content = "(Tapi setelah itu, beberapa hari berlalu sebelum aku melihat Migard lagi.)",
  ui_story_30930601_107_dialog_content = "Kamu punya kabar tentang Migard?",
  ui_story_30930601_108_dialog_content = "Tidak juga. Tapi, setahuku dia belum keluar dari lounge-nya selama berhari-hari.",
  ui_story_30930601_109_dialog_content = "Sepertinya sang bos telah kehilangan mekanisme penjelajahannya, ya?",
  ui_story_30930601_110_dialog_content = "Oh, iya, belum lama ini aku menemukan game baru untuk dimainkan!",
  ui_story_30930601_111_dialog_content = "Bagaimana, PlayerName? Mau bermain bersama?",
  ui_story_30930601_112_dialog_content = "Tidak hari ini, Gronru. Aku ingin memeriksa keadaannya.",
  ui_story_30930601_113_dialog_content = "Sudah tidak takut menghadapinya sendirian, ya, PlayerName? Wah, kamu naik level!",
  ui_story_30930601_114_dialog_content = "(Eh...)",
  ui_story_30930601_115_dialog_content = "(Masih terlalu takut, sih. Mungkin sebaiknya aku mundur saja sekarang...)",
  ui_story_30930601_116_dialog_content = "(Pelan-pelan... Dengan tenang...)",
  ui_story_30930601_117_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_30930601_118_dialog_content = "Ada ledakan?!",
  ui_story_30930601_119_dialog_content = "Migard! Kamu baik-baik saja?!",
  ui_story_30930601_120_dialog_content = "Migard!",
  ui_story_30930601_121_dialog_content = "<color=#e8d9bb>Hancur...</color>",
  ui_story_30930601_122_dialog_content = "Oh... Rupanya kamu, PlayerName.",
  ui_story_30930601_123_dialog_content = "Ledakan barusan...",
  ui_story_30930601_124_dialog_content = "Itu hanya sedikit efek samping dari eksperimen, kok.",
  ui_story_30930601_125_dialog_content = "Yah, asalkan kamu baik-baik saja... Kita sudah beberapa hari tidak bertemu, Migard. Aku jadi cemas.",
  ui_story_30930601_126_dialog_content = "Wah, kamu berani juga mengunjungiku padahal sangat takut, ya?",
  ui_story_30930601_127_dialog_content = "Kamu bahkan langsung masuk ke lounge-ku... Mengkhawatirkan keselamatanku, ya?",
  ui_story_30930601_128_dialog_content = "PlayerName... Kamu sangat baik hati...",
  ui_story_30930601_129_dialog_content = "Tapi, kalau kulihat lagi, sepertinya aku memang sudah lama tidak menghirup udara segar.",
  ui_story_30930601_130_dialog_content = "Apa eksperimenmu sudah selesai?",
  ui_story_30930601_131_dialog_content = "Ya... akhirnya aku mendapatkan hasil yang memuaskan meski butuh waktu lama.",
  ui_story_30930601_132_dialog_content = "Kamu kelihatan jauh lebih santai... Eksperimennya berhasil, ya?",
  ui_story_30930601_133_dialog_content = "Kurasa begitu.",
  ui_story_30930601_134_dialog_content = "Apa lagi, kamu yang melakukan eksperimen. Tak ada eksperimen yang gagal di tanganmu dan Divine Spines-mu, Migard.",
  ui_story_30930601_135_dialog_content = "Kamu juga sudah meluangkan banyak waktu dan usaha untuk eksperimen ini.",
  ui_story_30930601_136_dialog_content = "Tidak, PlayerName. Eksperimennya gagal total.",
  ui_story_30930601_137_dialog_content = "Akhirnya, masih ada banyak kotoran dalam kristal itu.",
  ui_story_30930601_138_dialog_content = "Hah?",
  ui_story_30930601_139_dialog_content = "Ada terlalu banyak variabel dan faktor yang harus diperhitungkan.",
  ui_story_30930601_140_dialog_content = "Seolah-olah kita tiba-tiba mendapati bahwa Barton bisa bertahan duduk di sauna yang bersuhu 100°C.",
  ui_story_30930601_141_dialog_content = "Mungkin itu karena tekadnya yang gigih.",
  ui_story_30930601_142_dialog_content = "Atau mungkin dia bertaruh dengan Wrath, dan tidak mau kalah.",
  ui_story_30930601_143_dialog_content = "Atau mungkin dia sudah memodifikasi seluruh tubuhnya menjadi senjata perang yang terbuat dari baja.",
  ui_story_30930601_144_dialog_content = "Mungkin, kita bisa melewati bagian tentang Barton dan sauna...",
  ui_story_30930601_145_dialog_content = "Jadi...",
  ui_story_30930601_146_dialog_content = "Jangan gugup begitu, dong. Aku baik-baik saja, justru sedang sangat bersemangat.",
  ui_story_30930601_147_dialog_content = "Suasana hatimu bahkan tetap bagus walau eksperimenmu gagal?",
  ui_story_30930601_148_dialog_content = "Menurutmu, meraih kesuksesan dalam eksperimen tidak semudah itu, 'kan, PlayerName?",
  ui_story_30930601_149_dialog_content = "Sulit dikatakan sih, apalagi selama ini aku hanya melihat keberhasilan proyekmu,",
  ui_story_30930601_150_dialog_content = "Kamu benar. Eksperimen yang berhasil telah mengalahkan yang gagal dan menutupi semuanya.",
  ui_story_30930601_151_dialog_content = "Bahkan keberhasilan sekecil apa pun diraih setelah ribuan kegagalan.",
  ui_story_30930601_152_dialog_content = "Keberhasilan itu sulit diraih, apalagi jika menyangkut sains. Memang, biasanya tidak disengaja dan selalu kecil hasilnya.",
  ui_story_30930601_153_dialog_content = "Bahkan keberhasilan Divine Spines milikku hanyalah kebetulan semata.",
  ui_story_30930601_154_dialog_content = "Dalam banyak kasus, peneliti menghabiskan seluruh hidupnya untuk meraih beberapa kesuksesan.",
  ui_story_30930601_155_dialog_content = "Tapi, pada akhirnya, semua kesuksesan itu hanya mendorong hambatan kognitif kita selangkah lebih dekat ke luasnya alam semesta.",
  ui_story_30930601_156_dialog_content = "Setelah mendengar itu, sepertinya sains hanya berisi rintangan...",
  ui_story_30930601_157_dialog_content = "Tapi, di situlah letak kegembiraan sebuah riset.",
  ui_story_30930601_158_dialog_content = "Aku tak pernah takut gagal. Lagi pula, menyangkal gagasan adalah bagian dasar dalam penelitian.",
  ui_story_30930601_159_dialog_content = "Sama-sama, terima kasih, PlayerName.",
  ui_story_30930601_160_dialog_content = "Kepedulianmu sudah lebih dari cukup untuk memberiku kekuatan agar terus bergerak maju.",
  ui_story_30930601_161_dialog_content = "Migard...",
  ui_story_30930601_162_dialog_content = "Meski begitu, aku tetap seorang ahli biologi yang berbakat.",
  ui_story_30930601_163_dialog_content = "Jika memulai proyek eksperimental denganku, peluang keberhasilan akan lebih tinggi daripada jika bersama orang lain.",
  ui_story_30930601_164_dialog_content = "Itulah sebabnya...",
  ui_story_30930601_165_dialog_content = "Di eksperimen berikutnya, aku menyelidiki pikiran dan struktur otak para gamer biasa.",
  ui_story_30930601_166_dialog_content = "Dan asistenku untuk eksperimen ini... tak lain adalah kamu, PlayerName!",
  ui_story_30930601_167_option_content = "Tidak.",
  ui_story_30930601_168_option_content = "Tidak mau.",
  ui_story_30930601_169_option_content = "Sama sekali tidak mau.",
  ui_story_30930601_170_dialog_content = "Kamu cepat sekali menolakku, hmm...?",
  ui_story_30930601_171_dialog_content = "(Kenapa rasanya dia tidak mau ditolak, ya...?)",
  ui_story_30930601_172_dialog_content = "(Lalu tatapan matanya... Lebih mengerikan dari biasanya!!)",
  ui_story_30930601_173_dialog_content = "Kalau aku tidak bisa menjadikan Gronru sebagai subjek pengujian, orang yang sangat dipengaruhi olehnya juga boleh. Seseorang seperti dirimu, PlayerName...",
  ui_story_30930601_174_dialog_content = "Wah, aku sungguh beruntung. Material eksperimenku tiba pagi-pagi sekali!",
  ui_story_30930601_175_dialog_content = "Nah, sekarang saatnya dengan pelan dan hati-hati... membuka kepala PlayerName dan melihat isinya.",
  ui_story_30930601_176_dialog_content = "Sudah kubilang aku tak mau terlibat!",
  ui_story_30930601_177_dialog_content = "Berapa kali pun gagal, kita akan mencapai keberhasilan bersama-sama!",
  ui_story_30930601_178_dialog_content = "Ayo! Mari kita menguak misteri sains bersama-sama!",
  ui_story_30930601_179_dialog_content = "M-menjauhlah dariku! Toloooong!!!"
}
return config
